-- Queer Atlas: verified Poland, Estonia, Czechia, Switzerland and Austria events, batch 6.

begin;
alter table if exists public.events add column if not exists event_intel jsonb not null default '{}'::jsonb;
alter table if exists public.events add column if not exists ticket_url text;

with src as (
 select * from jsonb_to_recordset($qa_pecsa_batch6$
[
{"name":"Halina Just Wanna Have Fun Vol. 4","aliases":["Halina vol.4 Warsaw","Halina Just Wanna Have Fun Warsaw 2026"],"city":"warsaw","date":"2026-10-10","start_date":"2026-10-10","end_date":"2026-10-11","description":"Halina’s final 90s-and-00s chapter lands at Oczki as a loud, affectionate queer-pop reset: Spice Girls, Britney, Polish throwbacks and the kind of collective singing that turns nostalgia into chosen-family energy.","link":"https://stage24.pl/wydarzenia/halina-vol4-8239","ticket_url":"https://stage24.pl/wydarzenia/halina-vol4-8239","location":"Oczki, ul. Wojciecha Oczki 1A, Warsaw, Poland","lat":52.2231,"lng":21.0048,"vibe":"LGBTQ+ 90s/00s pop catharsis with maximal singalongs and late-night freedom","intel":{"hours":"Doors/ticket platform from 20:00; club programme from 22:00 Saturday 10 October 2026.","entry_wait":"Tickets are sold through Stage24; the final-edition appeal makes advance purchase wiser than relying on a late walk-up.","best_arrival":"Arrive near 22:00 for the full pop arc rather than joining only after the nostalgia peak.","crowd_mix":"LGBTQ+ people, women-loving-women, trans and non-binary guests, friends and allies are explicitly welcomed.","dress_code":"90s/00s pop excess is the natural read; no mandatory look is published.","host_inclusivity":"The event explicitly welcomes LGBTQ+ people and gender-diverse guests into a celebratory, non-exclusive dance floor.","lineup":"Pop-focused DJ programme; check organiser for final selectors.","age_limit":"18+.","source_urls":["https://stage24.pl/wydarzenia/halina-vol4-8239","https://bestofwarsaw.pl/en/events/halina-just-wanna-have-fun-vol-4/"],"research_status":"ticketing_listing_and_lgbtq_audience_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"Pride and Pain: Halloween Edition","aliases":["queer play party series Pride and Pain 18+","Pride and Pain Tallinn October 2026"],"city":"tallinn","date":"2026-10-10","start_date":"2026-10-10","end_date":"2026-10-11","description":"Pride and Pain makes spooky season a grounded LGBTQIA+ dungeon night: a trans-led, somatic approach to kink where new explorers and seasoned players meet under clear structure, care and actual consent culture.","link":"https://fienta.com/et/s/pride-and-pain","ticket_url":"https://fienta.com/et/s/pride-and-pain","location":"Kultus Club, Kopli, Tallinn, Estonia","lat":59.4508,"lng":24.7123,"vibe":"LGBTQIA+-only somatic kink and play party with spooky-season intimacy","intel":{"hours":"18:00 Saturday 10 October–02:00 Sunday 11 October 2026.","entry_wait":"Tickets start from €40; use the organiser’s sign-up channel and read participation information before travelling.","best_arrival":"Come for the 18:00 opening to receive the full grounding and consent structure rather than arriving mid-play.","crowd_mix":"LGBTQIA+-only guests, from newcomers to experienced kinksters, in a deliberately community-specific room.","dress_code":"Theme: kinky spooky season. Confirm practical requirements with the host; bring personal toys and snacks only if permitted by the event guidance.","host_inclusivity":"Hosted by trans woman Mother Ella, with a stated focus on queer sexuality, gender expression, neurodivergent unmasking and strong consent culture.","lineup":"Host-led play-party programme.","age_limit":"18+.","source_urls":["https://fienta.com/et/s/pride-and-pain","https://eventeeka.com/tallinn/event/queer-play-party-series-pride-and-pain-18/fi-192101"],"research_status":"official_ticketing_and_host_format_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"GEGEN PRAGUE","aliases":["Gegen Prague October 2026"],"city":"prague","date":"2026-10-03","start_date":"2026-10-03","end_date":"2026-10-04","description":"GEGEN returns to Fuchs2 for bodies that refuse containment: a fetish-techno night where queer visibility, pleasure and political refusal share one overheated floor.","link":"https://ra.co/events/2472999","ticket_url":"https://ra.co/events/2472999","location":"Fuchs2, Štvanice, 170 00 Prague, Czechia","lat":50.1023,"lng":14.4346,"vibe":"defiant queer fetish-techno with sex-positive visibility, consent and high-pressure release","intel":{"hours":"23:00 Saturday 3 October–06:00 Sunday 4 October 2026.","entry_wait":"Tickets are electronic-payment only. An e-ticket does not guarantee entry, but refused guests receive a door refund through the RA system.","best_arrival":"Arrive at 23:00 and allow time for the door process; it is part of how the party protects the inside space.","crowd_mix":"Queer, fetish and sex-positive dancers, alongside guests who understand that visibility and desire are political here.","dress_code":"Colours, fetish, latex, leather, rubber, sportswear, shiny, dirty or bare looks are encouraged; casual wear is not accepted.","host_inclusivity":"Consent, privacy and anti-discrimination rules are explicit; a visible awareness team is available and image recording is discouraged throughout.","lineup":"Cristian Marras, jardabpm, Mar/us, Samantha Togni; bodies by Dmi and Tomas.","age_limit":"18+.","source_urls":["https://ra.co/events/2472999"],"research_status":"ticketing_listing_door_policy_and_awareness_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"FEMXCORE: Hekate’s Ritual","aliases":["FEMXCORE Hekate’s Ritual","FEMXCORE Halloween 2026"],"city":"prague","date":"2026-10-31","start_date":"2026-10-31","end_date":"2026-11-01","description":"FEMXCORE summons Hekate at Bike Jesus: a FLINTA-primary Halloween crossing of Queer Bazaar, live electronics, hard techno, psytrance and the kind of regional creative network that makes a party feel like infrastructure.","link":"https://ra.co/events/2531658","ticket_url":"https://ra.co/events/2531658","location":"Bike Jesus, ostrov Štvanice 1125, 170 00 Praha 7-Holešovice, Czechia","lat":50.1050,"lng":14.4355,"vibe":"FLINTA-primary Halloween ritual joining queer market culture, experimental live music and hard club energy","intel":{"hours":"Queer Bazaar/outdoors from 19:00; paid live and club-night programme from 21:00 until 06:00 Sunday 1 November 2026.","entry_wait":"Outdoor and Revolution-stage access is free; paid entry is required for the live and club-night sections. Advance tickets range from 111–444 CZK.","best_arrival":"Come at 19:00 for the market and communal daylight-to-darkness transition, not only the late hard-techno segment.","crowd_mix":"Regional FLINTA creatives are centred; everyone is welcome when they respect the primary community and safer-space purpose.","dress_code":"Witchy self-expression fits the ritual, but no compulsory outfit is published.","host_inclusivity":"Awareness and harm reduction are on site; the venue is partially wheelchair accessible and the organiser invites advance contact for disability support.","lineup":"Nikki Madi, langlo, Freak Daddy, Mother Menace, XENEA, LUMRA, SAVBEA and Queer Bazaar contributors.","age_limit":"18+.","source_urls":["https://ra.co/events/2531658"],"research_status":"ticketing_listing_access_and_harm_reduction_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"UNDERCUT: Lesbians and Friends Unite","aliases":["UNDERCUT Lesbians and Friends Zurich"],"city":"zurich","date":"2026-10-10","start_date":"2026-10-10","end_date":"2026-10-11","description":"UNDERCUT is a Zürich room for lesbians and their people: a friendly, identity-expansive party where the invitation is less about fitting a scene than arriving as you are and finding a floor that makes space back.","link":"https://eventfrog.ch/de/p/partys/lgbtiq/undercut-lesbians-and-friends-unite-7495911821477438675.html","ticket_url":"https://eventfrog.ch/de/p/partys/lgbtiq/undercut-lesbians-and-friends-unite-7495911821477438675.html","location":"SOHO Zurich, Hardstrasse 260, 8005 Zürich, Switzerland","lat":47.3877,"lng":8.5208,"vibe":"lesbian-centred Zurich club night with open queer community warmth","intel":{"hours":"Saturday 10 October 2026; confirm final doors and finish time through the active Eventfrog listing.","entry_wait":"Online sales close early on the event day; use the live ticket page for remaining capacity and door terms.","best_arrival":"Arrive close to published doors so a small community venue stays social rather than becoming a late queue.","crowd_mix":"Lesbians are centred, while all genders and identities are explicitly welcomed.","dress_code":"No mandatory dress code is published; personal expression and dance comfort are the right read.","host_inclusivity":"The organiser makes the gender- and identity-inclusive invitation explicit rather than marketing the event as a generic women’s night.","lineup":"Check Eventfrog for current programme.","age_limit":"Confirm through ticketing.","source_urls":["https://eventfrog.ch/de/p/partys/lgbtiq/undercut-lesbians-and-friends-unite-7495911821477438675.html"],"research_status":"ticketing_listing_verified_hours_pending","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"HYPERTRASH pres. umru","aliases":["Hypertrash umru Vienna 2026"],"city":"vienna","date":"2026-10-03","start_date":"2026-10-03","end_date":"2026-10-04","description":"HYPERTRASH turns Flex into Vienna’s hyperpop fault line: umru, Mavi Phoenix and a stack of local troublemakers gather queers, misfits and otherlings for a night that refuses normal as a setting.","link":"https://ra.co/events/2527574","ticket_url":"https://ra.co/events/2527574","location":"Flex, Abgang Augartenbrücke, 1010 Vienna, Austria","lat":48.2168,"lng":16.3698,"vibe":"hyperpop and techno for queers, misfits and otherlings with community-ticket access","intel":{"hours":"23:00 Saturday 3 October–06:00 Sunday 4 October 2026.","entry_wait":"Presale is €10/12/15 and door is €18; limited pay-what-you-want community tickets are available directly from the organiser.","best_arrival":"Arrive at 23:00 to catch the full cross-genre bill and avoid the late Flex bottleneck.","crowd_mix":"Queers, misfits, otherlings, lovers of trash and hyperpop devotees are openly named as the event’s community.","dress_code":"No fixed code is published; bring the strange version of yourself, but smart glasses are explicitly not allowed.","host_inclusivity":"safer.nights handles awareness and selection, while pay-what-you-want tickets make access part of the event design.","lineup":"umru, Mavi Phoenix hybrid, DJ DIAMOND, DJ Dryhump, DJ NaBumms, esti.d, hapuk, Peter Puenktlich, XaviorTM and yarx.","age_limit":"18+ with photo ID; no exceptions.","source_urls":["https://ra.co/events/2527574"],"research_status":"ticketing_listing_awareness_and_access_verified","updated_at":"2026-09-26T00:00:00Z"}}
]
$qa_pecsa_batch6$) e(name text,aliases jsonb,city text,date date,start_date date,end_date date,description text,link text,ticket_url text,location text,lat double precision,lng double precision,vibe text,intel jsonb)
), matched as (
 select s.*,x.id existing_id from src s left join lateral(select e.id from public.events e where lower(trim(e.city))=lower(trim(s.city)) and (lower(regexp_replace(trim(e.name),'[^a-z0-9]+','','gi'))=lower(regexp_replace(trim(s.name),'[^a-z0-9]+','','gi')) or exists(select 1 from jsonb_array_elements_text(s.aliases) a where lower(regexp_replace(trim(e.name),'[^a-z0-9]+','','gi'))=lower(regexp_replace(trim(a),'[^a-z0-9]+','','gi'))) or (e.start_date=s.start_date and lower(nullif(trim(e.link),'')) in(lower(s.link),lower(s.ticket_url)))) limit 1)x on true
), updated as (
 update public.events e set name=s.name,description=s.description,link=s.link,ticket_url=s.ticket_url,date=s.date,start_date=s.start_date,end_date=s.end_date,location=s.location,lat=s.lat,lng=s.lng,vibe=s.vibe,vibe_tags=array[]::text[],event_intel=s.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now()) from matched s where e.id=s.existing_id returning e.id
)
insert into public.events(name,city,description,link,ticket_url,date,start_date,end_date,location,lat,lng,vibe,vibe_tags,event_intel,seo_indexable,seo_quality_status,updated_at)
select name,city,description,link,ticket_url,date,start_date,end_date,location,lat,lng,vibe,array[]::text[],intel,true,'approved',timezone('utc',now()) from matched where existing_id is null;

do $qa_pecsa_batch6_guard$
begin
 if exists(select 1 from public.events where event_intel->>'updated_at'='2026-09-26T00:00:00Z' and (coalesce(trim(description),'')='' or coalesce(trim(location),'')='' or jsonb_array_length(coalesce(event_intel->'source_urls','[]'::jsonb))=0)) then raise exception 'Poland Estonia Czechia Switzerland Austria batch missing editorial data'; end if;
end;
$qa_pecsa_batch6_guard$;
commit;
